void MergeLists(LinkList La, LinkList Lb) {
    LNode *p = La->next;
    LNode *q = Lb->next;
    LNode *tail = La;
    while (p != NULL && q != NULL) {
        if (p->data <= q->data) {
            tail->next = p;
            p = p->next;
        } else {
            tail->next = q;
            q = q->next;
        }
        tail = tail->next;
    }
    tail->next = (p != NULL) ? p : q;
    Lb->next = NULL;
}

