void RemoveAbsDuplicates(LinkList L, int maxValue) {
    int *visited = new int[maxValue + 1]();
    LNode *pre = L;
    LNode *p = L->next;
    while (p != NULL) {
        int value = p->data < 0 ? -p->data : p->data;
        if (visited[value] == 0) {
            visited[value] = 1;
            pre = p;
            p = p->next;
        } else {
            pre->next = p->next;
            delete p;
            p = pre->next;
        }
    }
    delete[] visited;
}

