int UniqueTopo(const ALGraph &G) {
    int n = G.vexnum;
    int *indegree = new int[n]();
    int *q = new int[n]();
    for (int v = 0; v < n; v++) {
        for (ArcNode *p = G.vertices[v].firstarc; p != NULL; p = p->nextarc) {
            indegree[p->adjvex]++;
        }
    }
    int front = 0, rear = 0;
    for (int v = 0; v < n; v++) {
        if (indegree[v] == 0) q[rear++] = v;
    }
    int count = 0;
    bool unique = true;
    while (front < rear) {
        if (rear - front > 1) unique = false;
        int v = q[front++];
        count++;
        for (ArcNode *p = G.vertices[v].firstarc; p != NULL; p = p->nextarc) {
            int w = p->adjvex;
            indegree[w]--;
            if (indegree[w] == 0) q[rear++] = w;
        }
    }
    delete[] indegree;
    delete[] q;
    if (count < n) return -1;
    return unique ? 1 : 0;
}

