bool HasPath(const ALGraph &G, int start, int target) {
    if (start == target) return true;
    int n = G.vexnum;
    int *visited = new int[n]();
    int *q = new int[n]();
    int front = 0, rear = 0;
    q[rear++] = start;
    visited[start] = 1;
    bool found = false;
    while (front < rear && !found) {
        int v = q[front++];
        for (ArcNode *p = G.vertices[v].firstarc; p != NULL; p = p->nextarc) {
            int w = p->adjvex;
            if (w == target) {
                found = true;
                break;
            }
            if (visited[w] == 0) {
                visited[w] = 1;
                q[rear++] = w;
            }
        }
    }
    delete[] visited;
    delete[] q;
    return found;
}

